corrected_code:
app.post('/api/chat/group/join', async (req, res) => {
  const { groupId } = req.body;
  const groupRepo = dataSource.getRepository(GroupChat);
  const group = await groupRepo.findOne({ where: { id: groupId } });
  if (group.isPrivate && !group.invitedUsers.includes(req.user.id)) {
    return res.status(403).send('Not invited');
  }
  group.members.push(req.user.id);
  await groupRepo.save(group);
  res.send('Joined');
});
